//! The rows of `entrypoints.tsv`, and reading, writing and comparing them.

use std::collections::BTreeSet;
use std::path::Path;
use std::str::FromStr;

use rootcause::prelude::*;
use serde::Deserialize;

#[cfg(test)]
mod test;

/// First line of the generated file.
const GENERATED_NOTICE: &str =
    "# Generated by cargo run -p xtask -- email-coverage list. Do not edit.";

/// Column names, in file order.
const HEADER: &str = "kind\tkey\tproviders\tmatch\tsource";

/// What sort of entry point a row is.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, Hash, Deserialize, strum::Display, strum::EnumString,
)]
#[serde(rename_all = "lowercase")]
#[strum(serialize_all = "lowercase")]
pub enum Kind {
    /// A route of the email service's HTTP API.
    Http,
    /// A case a provider webhook handler tells apart.
    Webhook,
    /// A GraphQL resolver.
    Graphql,
    /// A message type on a queue an email worker consumes.
    Queue,
    /// An event published to a Kafka topic.
    Kafka,
    /// A push to the connection gateway.
    Gateway,
    /// An agent tool.
    Tool,
    /// A scheduled or triggered lambda.
    Lambda,
    /// A provider API method the service calls.
    Provider,
    /// A background loop, listed but not counted.
    Loop,
    /// A route of another service that carries an email function out,
    /// listed by hand.
    Elsewhere,
}

/// Which mail providers an entry point applies to.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, Hash, Deserialize, strum::Display, strum::EnumString,
)]
#[serde(rename_all = "lowercase")]
#[strum(serialize_all = "lowercase")]
pub enum Providers {
    /// Gmail inboxes only.
    Gmail,
    /// Outlook inboxes only.
    Outlook,
    /// Inboxes of either provider.
    Both,
}

/// One entry point.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Row {
    /// What sort of entry point this is.
    pub kind: Kind,
    /// Its name, unique within the kind.
    pub key: String,
    /// The providers it applies to.
    pub providers: Providers,
    /// For JSON message kinds, how to recognise the message: `*` matches
    /// any, `<json-pointer>` needs that pointer to exist, and
    /// `<json-pointer>=<string>` needs that string at the pointer. Empty for
    /// the other kinds.
    pub matcher: String,
    /// Where it is defined, as a repository-relative `path:line`.
    pub source: String,
}

impl Row {
    /// The row without the line of its source: a line moves whenever the
    /// file above it changes, which is no change to the entry point.
    fn identity(&self) -> String {
        let file = self
            .source
            .rsplit_once(':')
            .map_or(self.source.as_str(), |(file, _)| file);
        format!(
            "{}\t{}\t{}\t{}\t{file}",
            self.kind, self.key, self.providers, self.matcher
        )
    }

    fn line(&self) -> String {
        format!(
            "{}\t{}\t{}\t{}\t{}",
            self.kind, self.key, self.providers, self.matcher, self.source
        )
    }
}

/// Orders rows by kind name, then key.
pub(crate) fn sort(rows: &mut [Row]) {
    rows.sort_by(|a, b| (a.kind.to_string(), &a.key).cmp(&(b.kind.to_string(), &b.key)));
}

/// The text of `entrypoints.tsv` for `rows`, which the caller has sorted.
pub fn render_tsv(rows: &[Row]) -> String {
    let mut text = format!("{GENERATED_NOTICE}\n{HEADER}\n");
    for row in rows {
        text.push_str(&row.line());
        text.push('\n');
    }
    text
}

/// Reads the rows of an `entrypoints.tsv`, skipping `#` comment lines.
pub fn read_tsv(path: &Path) -> Result<Vec<Row>, Report> {
    let text =
        std::fs::read_to_string(path).context(format!("could not read {}", path.display()))?;
    parse_tsv(&text, &path.display().to_string())
}

/// Parses the text of an `entrypoints.tsv`; `origin` names it in errors.
pub fn parse_tsv(text: &str, origin: &str) -> Result<Vec<Row>, Report> {
    let mut lines = text
        .lines()
        .enumerate()
        .filter(|(_, line)| !line.starts_with('#'));

    match lines.next() {
        Some((_, HEADER)) => {}
        _ => bail!("{origin}: the first line after the comments is not the column header"),
    }

    lines
        .map(|(index, line)| {
            let at = format!("{origin}:{}", index + 1);
            let columns: Vec<&str> = line.split('\t').collect();
            let [kind, key, providers, matcher, source] = columns[..] else {
                bail!(
                    "{at}: expected 5 tab-separated columns, found {}",
                    columns.len()
                );
            };

            Ok(Row {
                kind: Kind::from_str(kind).map_err(|_| report!("{at}: unknown kind `{kind}`"))?,
                key: key.to_owned(),
                providers: Providers::from_str(providers)
                    .map_err(|_| report!("{at}: unknown providers `{providers}`"))?,
                matcher: matcher.to_owned(),
                source: source.to_owned(),
            })
        })
        .collect()
}

/// How the checked-in rows differ from the generated ones: a `-` line for
/// each row only the file has, then a `+` line for each row only the code
/// gives. Empty when they agree.
pub fn diff(checked_in: &[Row], generated: &[Row]) -> Vec<String> {
    let in_file: BTreeSet<String> = checked_in.iter().map(Row::identity).collect();
    let in_code: BTreeSet<String> = generated.iter().map(Row::identity).collect();

    let removed = in_file.difference(&in_code).map(|line| format!("- {line}"));
    let added = in_code.difference(&in_file).map(|line| format!("+ {line}"));
    removed.chain(added).collect()
}
